@spec generators_spec  src=tests/specs/generators_spec.lua  loc=638  cases=47
@exercises generators (generators)
@surface   generators.glyphOf, generators.labelOf, generators.fieldsFor, generators.parksNotes, generators.parkWindows, generators.continuousTargets, generators.chainDestType, generators.destOf, generators.retarget, generators.fieldRange, generators.thinCurve

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 8-10
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 13-16
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 17-19
  @fn triangle()  @ 23-29
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.
  @fn pts(rows)  @ 33-39
      -- Curve points positionally: {ppq, val, shape?, tension?}; shape defaults to linear, the one kind
      -- thinCurve is allowed to drop.

# Cases
  @case 'every registered kind carries a glyph, one codepoint, shared with no other kind'  [pure]  @ 46-55
  @case 'glyphOf resolves off the registry, and falls back for a kind the registry has lost'  [pure]  @ 59-63
  @case 'labelOf resolves off the registry, and keeps a lost kind\'s name in the mark'  [pure]  @ 67-72
  @case 'fieldsFor gives a lost kind no rows'  [pure]  @ 76-80
  @case 'slide glides in: flat hold, slur to the interval, then hand off to tm\'s close'  [pure]  @ 86-97
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 101-105
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 109-113
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 117-122
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 126-130
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 134-138
  @case 'trill tiles the window from its start, alternating host pitch with the cents demand'  [pure]  @ 144-157
  @case 'trill measures its demand from what the host sounds, detune and all'  [pure]  @ 161-169
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 175-180
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 184-199
  @case 'the ownership predicates ignore bypass: a bypassed chain still parks and still scopes its target'  [pure]  @ 203-213
  @case 'chainDestType demotes a bypassed replace stage to augment, and only that stage'  [pure]  @ 217-227
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 233-238
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 242-250
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 254-259
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 263-269
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 273-279
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 283-289
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 293-300
  @case 'sine on a cc dest tiles the window with extrema in cc steps, anchored 0 at both ends'  [pure]  @ 306-319
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 325-340
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 344-354
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 360-372
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 376-385
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 389-400
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 406-423
  @case 'chord-stamp moves every voice by the cents from its root to the trigger'  [pure]  @ 427-447
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 451-467
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 471-481
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 487-504
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 508-517
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 521-530
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 534-543
  @case 'thinCurve returns a degenerate curve verbatim -- endpoints are never candidates'  [pure]  @ 549-556
  @case 'thinCurve collapses a collinear linear run to its endpoints'  [pure]  @ 560-567
  @case 'thinCurve drops a spike whose vertical error only meets the tolerance'  [pure]  @ 571-575
  @case 'thinCurve keeps a spike whose vertical error exceeds the tolerance'  [pure]  @ 579-582
  @case 'thinCurve keeps a stepped run whole, collinear though its points are'  [pure]  @ 586-590
  @case 'thinCurve rides a curved point through with its tension intact'  [pure]  @ 594-600
  @case 'thinCurve lets a non-linear point pin its successor as well as itself'  [pure]  @ 604-609
  @case 'thinCurve treats a missing shape as non-linear -- under-thin over silently ramping'  [pure]  @ 613-617
  @case 'thinCurve keeps a stack of coincident points -- a zero-width span has no chord'  [pure]  @ 621-625
  @case 'thinCurve gives a dual-point pair no special protection'  [pure]  @ 629-635

